import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

layer_norm_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void layer_norm_kernel(const float* __restrict__ input,
                                   const float* __restrict__ gamma,
                                   const float* __restrict__ beta,
                                   float* __restrict__ output,
                                   int inner_size,
                                   float eps) {
    int n = blockIdx.x;
    const float* x = input + (size_t)n * inner_size;
    float* out = output + (size_t)n * inner_size;
    extern __shared__ float sdata[];
    float* ssum = sdata;
    float* ssqsum = sdata + blockDim.x;
    float sum = 0.f;
    float sqsum = 0.f;
    int vec_size = inner_size / 4;
    const float4* x4 = reinterpret_cast<const float4*>(x);
    for (int i = threadIdx.x; i < vec_size; i += blockDim.x) {
        float4 v = x4[i];
        sum += v.x + v.y + v.z + v.w;
        sqsum += v.x * v.x + v.y * v.y + v.z * v.z + v.w * v.w;
    }
    for (int i = vec_size * 4 + threadIdx.x; i < inner_size; i += blockDim.x) {
        float v = x[i];
        sum += v;
        sqsum += v * v;
    }
    ssum[threadIdx.x] = sum;
    ssqsum[threadIdx.x] = sqsum;
    __syncthreads();
    for (int stride = blockDim.x / 2; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) {
            ssum[threadIdx.x] += ssum[threadIdx.x + stride];
            ssqsum[threadIdx.x] += ssqsum[threadIdx.x + stride];
        }
        __syncthreads();
    }
    __shared__ float mean_s, invstd_s;
    if (threadIdx.x == 0) {
        float m = ssum[0] / inner_size;
        float var = ssqsum[0] / inner_size - m * m;
        if (var < 0.f) var = 0.f;
        mean_s = m;
        invstd_s = rsqrtf(var + eps);
    }
    __syncthreads();
    float mean = mean_s;
    float invstd = invstd_s;
    const float4* gamma4 = reinterpret_cast<const float4*>(gamma);
    const float4* beta4 = reinterpret_cast<const float4*>(beta);
    float4* out4 = reinterpret_cast<float4*>(out);
    for (int i = threadIdx.x; i < vec_size; i += blockDim.x) {
        float4 v = x4[i];
        float4 g = gamma4[i];
        float4 b = beta4[i];
        float4 o;
        o.x = (v.x - mean) * invstd * g.x + b.x;
        o.y = (v.y - mean) * invstd * g.y + b.y;
        o.z = (v.z - mean) * invstd * g.z + b.z;
        o.w = (v.w - mean) * invstd * g.w + b.w;
        out4[i] = o;
    }
    for (int i = vec_size * 4 + threadIdx.x; i < inner_size; i += blockDim.x) {
        float v = x[i];
        out[i] = (v - mean) * invstd * gamma[i] + beta[i];
    }
}

torch::Tensor layer_norm_cuda(torch::Tensor x, torch::Tensor gamma, torch::Tensor beta, double eps) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(x.dtype() == torch::kFloat32, "x must be float32");

    auto x_contig = x.contiguous();
    auto gamma_contig = gamma.contiguous();
    auto beta_contig = beta.contiguous();

    int64_t inner_size = gamma_contig.numel();
    int64_t total = x_contig.numel();
    int64_t N = total / inner_size;

    auto output = torch::empty_like(x_contig);

    int threads = 256;
    dim3 grid(N);
    size_t shared_mem = 2 * threads * sizeof(float);

    layer_norm_kernel<<<grid, threads, shared_mem>>>(
        x_contig.data_ptr<float>(),
        gamma_contig.data_ptr<float>(),
        beta_contig.data_ptr<float>(),
        output.data_ptr<float>(),
        (int)inner_size,
        (float)eps
    );

    return output;
}
"""

layer_norm_header = r"""
torch::Tensor layer_norm_cuda(torch::Tensor x, torch::Tensor gamma, torch::Tensor beta, double eps);
"""

layer_norm_ext = load_inline(
    name="layer_norm_ext",
    cpp_sources=layer_norm_header,
    cuda_sources=layer_norm_source,
    functions=["layer_norm_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Simple model that performs Layer Normalization using a custom CUDA kernel.
    """
    def __init__(self, normalized_shape: tuple):
        super(ModelNew, self).__init__()
        self.normalized_shape = normalized_shape
        self.weight = nn.Parameter(torch.ones(normalized_shape))
        self.bias = nn.Parameter(torch.zeros(normalized_shape))
        self.eps = 1e-5

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = x.cuda().contiguous()
        weight = self.weight.to(x.device)
        bias = self.bias.to(x.device)
        return layer_norm_ext.layer_norm_cuda(x, weight, bias, self.eps)


batch_size = 16
features = 64
dim1 = 256
dim2 = 256


def get_inputs():
    x = torch.rand(batch_size, features, dim1, dim2)
    return [x]


def get_init_inputs():
    return [(features, dim1, dim2)]

